import { z } from "zod";

// Shapes of the Codex app-server messages Away consumes, taken from the TypeScript bindings
// generated by `codex app-server generate-ts` for codex-cli 0.162.1 (ts/v2/*). Objects are loose
// because the server adds fields beyond the stable types (for example `emittedAtMs`).

export const ThreadResponseSchema = z.looseObject({ thread: z.looseObject({ id: z.string() }) });
export const TurnResponseSchema = z.looseObject({ turn: z.looseObject({ id: z.string() }) });
export const AccountResponseSchema = z.looseObject({
  account: z.looseObject({ type: z.string() }).nullable(),
  requiresOpenaiAuth: z.boolean(),
});

const UserInputSchema = z.looseObject({ type: z.string(), text: z.string().optional() });

export const ThreadItemSchema = z.discriminatedUnion("type", [
  z.looseObject({ type: z.literal("userMessage"), id: z.string(), content: z.array(UserInputSchema) }),
  z.looseObject({ type: z.literal("agentMessage"), id: z.string(), text: z.string() }),
  z.looseObject({
    type: z.literal("commandExecution"),
    id: z.string(),
    command: z.string(),
    cwd: z.string(),
    status: z.string(),
    aggregatedOutput: z.string().nullable(),
    exitCode: z.number().nullable(),
  }),
  z.looseObject({
    type: z.literal("fileChange"),
    id: z.string(),
    changes: z.array(z.looseObject({ path: z.string(), kind: z.looseObject({ type: z.string() }), diff: z.string() })),
    status: z.string(),
  }),
  z.looseObject({
    type: z.literal("mcpToolCall"),
    id: z.string(),
    server: z.string(),
    tool: z.string(),
    status: z.string(),
    arguments: z.unknown(),
    result: z.unknown(),
    error: z.looseObject({ message: z.string() }).nullable(),
  }),
]);
export type ThreadItem = z.infer<typeof ThreadItemSchema>;

export const NotificationSchemas = {
  "item/started": z.looseObject({ item: z.looseObject({ type: z.string() }) }),
  "item/completed": z.looseObject({ item: z.looseObject({ type: z.string() }) }),
  "item/agentMessage/delta": z.looseObject({ itemId: z.string(), delta: z.string() }),
  "item/reasoning/summaryTextDelta": z.looseObject({ itemId: z.string(), delta: z.string() }),
  "item/commandExecution/outputDelta": z.looseObject({ itemId: z.string(), delta: z.string() }),
  "turn/started": z.looseObject({ turn: z.looseObject({ id: z.string() }) }),
  "turn/completed": z.looseObject({
    turn: z.looseObject({
      id: z.string(),
      status: z.enum(["completed", "interrupted", "failed", "inProgress"]),
      error: z.looseObject({ message: z.string() }).nullable().optional(),
    }),
  }),
  error: z.looseObject({ error: z.looseObject({ message: z.string() }), willRetry: z.boolean() }),
  "serverRequest/resolved": z.looseObject({ requestId: z.union([z.string(), z.number()]) }),
} as const;
export type NotificationMethod = keyof typeof NotificationSchemas;

export const CommandApprovalParamsSchema = z.looseObject({
  itemId: z.string(),
  command: z.string().nullable().optional(),
  cwd: z.string().nullable().optional(),
  reason: z.string().nullable().optional(),
});
export const FileChangeApprovalParamsSchema = z.looseObject({
  itemId: z.string(),
  reason: z.string().nullable().optional(),
});
export const UserInputRequestParamsSchema = z.looseObject({
  questions: z.array(
    z.looseObject({
      id: z.string(),
      header: z.string(),
      question: z.string(),
      isOther: z.boolean(),
      isSecret: z.boolean(),
      options: z.array(z.looseObject({ label: z.string(), description: z.string() })).nullable(),
    }),
  ),
});
